const notifier=()=>{const t=document.getElementById("notification"),r=1e3;let e;return{notify:function(n,o){!t||!n||(o=o||r,t.innerHTML=n,t.classList.add("active"),e&&clearTimeout(e),e=window.setTimeout(()=>{t.classList.remove("active"),e=void 0,window.setTimeout(()=>{t.innerHTML=""},1e3)},o))}}},serviceWorkerSetup=async()=>{if(!("serviceWorker"in navigator)){document.querySelectorAll(".pwa").forEach(e=>{e.remove()});return}const r=(await navigator.serviceWorker.getRegistrations()).map(e=>e.unregister());await Promise.all(r),navigator.serviceWorker.register("/static/js/serviceworker.js",{start_url:"/",scope:"/"}).then(()=>console.log("Service Worker registered")).catch(e=>console.error("Service Worker registration failed",e))},home=()=>{const t=document.querySelector("#new-room form .phantom"),r=t.getAttribute("title"),e=document.getElementById("phantom"),n=document.getElementById("unlisted");if(serviceWorkerSetup(),!t||!r||!e||!n)return;const o=()=>{e.checked&&n.checked?t.setAttribute("title","Phantom & unlisted room"):t.setAttribute("title",r)};e.addEventListener("change",o),n.addEventListener("change",o);const i=notifier();document.querySelectorAll(".pwa").forEach(s=>{const c='<a href="https://developer.mozilla.org/en-US/docs/Web/Progressive_web_apps/Guides/Installing" target="_blank">Check how to install PWA</a>';s.addEventListener("click",()=>{i.notify(c,3e3)})})};home();
